// Стандарт С++20

#include <iostream>                                               // Подключение заголовочного файла для работы со стандартными потоками ввода-вывода (std::cout, std::cin) и манипулятором std::ws;
#include <format>                                                 // Подключение заголовочного файла для современного типобезопасного форматирования текста через std::format;
#include <string>                                                 // Подключение заголовочного файла для применения класса std::string для работы со строками и функции std::getline;
#include <memory>                                                 // Подключение заголовочного файла для работы с динамической памятью через умные указатели;

namespace                                                         // Объявление безымянного пространства имен для ограничения видимости текущей единицей трансляции;
{
    struct MarketAnalysis                                         // Объявление структуры типа MarketAnalysis, состоящей из 3 полей;
    {
        std::string name_pizza{};                                 // Поле для хранения названия компании-производителя пиццы (инициализация пустой строкой по умолчанию);
        float diameter{0.0f};                                     // Поле для хранения диаметра пиццы с дробной частью (инициализация нулем по умолчанию);
        float weight{0.0f};                                       // Поле для хранения веса пиццы с дробной частью (инициализация нулем по умолчанию);
    };
}

int main()
{
    const auto pizza = std::make_unique<MarketAnalysis>();        // std::make_unique<MarketAnalysis>() — функция make_unique выделяет пространство в памяти (в куче) для структуры типа MarketAnalysis и выдает умный указатель. Квалификатор const защищает от случайного изменения указателя. Тип auto указывает компилятору автоматически применить тип std::unique_ptr<MarketAnalysis>;

    std::cout << "Введите размер пиццы: ";                        // Объект std::cout с помощью оператора << выводит приглашение к вводу диаметра пиццы в консоль;
    std::cin >> pizza->diameter;                                  // Объект std::cin с помощью оператора >> вводит значение с клавиатуры в поле diameter, обращаясь к нему по адресу структуры через оператор членства-указателя;

    std::cout << "Введи производителя пиццы: ";                   // Объект std::cout с помощью оператора << выводит приглашение к вводу названия производителя в консоль;
    std::getline(std::cin >> std::ws, pizza->name_pizza);   // Функция std::getline(), принимая 1 аргумент — поток std::cin с манипулятором std::ws (очищающим буфер от оставшегося символа \n после ввода размера пиццы), записывает строку, введенную с клавиатуры, в поле name_pizza (2 аргумент), обращаясь к нему по адресу структуры через оператор членства-указателя;

    std::cout << "Введите вес пиццы: ";                           // Объект std::cout с помощью оператора << выводит приглашение к вводу веса пиццы в консоль;
    std::cin >> pizza->weight;                                    // Объект std::cin с помощью оператора >> вводит значение с клавиатуры в поле weight, обращаясь к нему по адресу структуры через оператор членства-указателя;

    std::cout << std::format("Производитель пиццы: {}\nРазмер: {}см\nВес: {}г", // Объект std::cout с помощью оператора << выводит отформатированную строку, сформированную функцией std::format;
                    pizza->name_pizza, pizza->diameter, pizza->weight);  // Передача значений полей объекта в аргументы форматирования, обращаясь к ним по адресу структуры через оператор членства-указателя;
}


